public class Main {

    static void procesar(Object obj) {
        String resultado = switch (obj) {
            case String s -> "Texto de " + s.length() + " caracteres";
            case Integer i -> (i % 2 == 0) ? "Entero par: " + i : "Entero impar: " + i;
            case Double d -> String.format("Decimal: %.2f", d);
            default -> "No soportado";
        };
        System.out.println(resultado);
    }

    public static void main(String[] args) {
        procesar("Java 21");
        procesar(10);
        procesar(7);
        procesar(2.71828);
        procesar(true);
    }
}

